def patches(d_code_lookup,rows):
    """yield (vaddr, new bytes); d_code_lookup(vaddr)->current 4 bytes, checked against the table"""
    for v,old in SITES:
        assert struct.unpack('<i',d_code_lookup(v))[0]==old,hex(v)
        yield v,struct.pack('<i',remap(old,rows))
def regen(code,B=0x10000):
    import capstone
    from capstone import x86_const as X
    md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_32); md.detail=True; out=[]
    for st,en in FUNCS:
        for ins in md.disasm(code[st-B:en-B],st):
            if ins.op_str=='esp, 0x4864' and ins.mnemonic in('sub','add'): out.append((ins.address+2,0x4864)); continue
            for op in ins.operands:
                if op.type==X.X86_OP_MEM and op.mem.base==X.X86_REG_ESP:
                    d=op.mem.disp
                    if remap(d,1024)!=d:
                        raw=code[ins.address-B:ins.address-B+ins.size]; pos=raw.find(struct.pack('<i',d))
                        assert pos>0 and raw.count(struct.pack('<i',d))==1,(hex(ins.address),ins.op_str)
                        out.append((ins.address+pos,d))
    return out
